'use client'

import {
  forwardRef,
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { springs } from '@/lib/motion-tokens'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Switch } from '@/components/ui/switch'

/* ─── SSR-safe layout effect ─── */

const useIsoLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect

/* ─── Icons ─── */

function SendIcon({ className }: { className?: string }) {
  return (
    <svg
      width={16}
      height={16}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={className}
    >
      <path d="M12 19V5" />
      <path d="M5 12l7-7 7 7" />
    </svg>
  )
}

function StopIcon({ className }: { className?: string }) {
  return (
    <svg
      width={14}
      height={14}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      className={className}
    >
      <rect x={4} y={4} width={16} height={16} rx={3} />
    </svg>
  )
}

const SEND_WAVE_GRADIENT =
  'linear-gradient(180deg, transparent, color-mix(in oklch, var(--color-accent), transparent 88%), color-mix(in oklch, var(--color-accent), transparent 82%), transparent)'

function SendWave({ reduceMotion }: { reduceMotion: boolean }) {
  return (
    <motion.div
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 z-10 overflow-hidden rounded-[inherit]"
      initial={{ opacity: 1 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
    >
      <motion.div
        className="absolute inset-x-0 top-0 h-[150%] blur-xl"
        style={{ background: SEND_WAVE_GRADIENT }}
        initial={{ y: '55%' }}
        animate={reduceMotion ? { y: '-17%' } : { y: '-105%' }}
        transition={reduceMotion ? { duration: 0 } : { duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
      />
    </motion.div>
  )
}

export type AiInputEffortLevel = 'low' | 'medium' | 'high'

const EFFORT_BAR_X = [1.5, 5.75, 10] as const
const EFFORT_BAR_WIDTH = 2.5
const EFFORT_BAR_BOTTOM = 12.5
const EFFORT_BAR_TALL = 10.5
const EFFORT_BAR_MID = 7.5
const EFFORT_BAR_SHORT = 4.5

const EFFORT_BAR_HEIGHTS: Record<AiInputEffortLevel, readonly [number, number, number]> = {
  low: [3.25, 4.75, 0],
  medium: [EFFORT_BAR_SHORT, EFFORT_BAR_MID, 0],
  high: [EFFORT_BAR_SHORT, EFFORT_BAR_MID, EFFORT_BAR_TALL],
}

const EFFORT_BAR_TRANSITION = { type: 'spring', stiffness: 380, damping: 34 } as const

export function AiInputEffortBarsIcon({
  level,
  className,
}: {
  level: AiInputEffortLevel
  className?: string
}) {
  const heights = EFFORT_BAR_HEIGHTS[level]
  return (
    <svg
      width={14}
      height={14}
      viewBox="0 0 14 14"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      {heights.map((height, index) => {
        const visible = height > 0
        return (
          <motion.rect
            key={EFFORT_BAR_X[index]}
            x={EFFORT_BAR_X[index]}
            width={EFFORT_BAR_WIDTH}
            rx={1}
            fill="currentColor"
            initial={false}
            animate={{
              height: visible ? height : 0,
              y: visible ? EFFORT_BAR_BOTTOM - height : EFFORT_BAR_BOTTOM,
              opacity: visible ? 1 : 0,
            }}
            transition={EFFORT_BAR_TRANSITION}
          />
        )
      })}
    </svg>
  )
}

function PlusIcon({ className }: { className?: string }) {
  return (
    <svg
      width={16}
      height={16}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={className}
    >
      <path d="M12 5v14M5 12h14" />
    </svg>
  )
}

export type AiInputMenuItem =
  | {
      type: 'action'
      value: string
      label: string
      icon?: ReactNode
      shortcut?: string
      disabled?: boolean
      onSelect?: () => void
      items?: undefined
    }
  | {
      type: 'toggle'
      value: string
      label: string
      icon?: ReactNode
      checked: boolean
      onCheckedChange: (checked: boolean) => void
    }
  | { type: 'separator'; value: string }
  | {
      type: 'submenu'
      value: string
      label: string
      icon?: ReactNode
      items: AiInputMenuItem[]
    }

export interface AiInputPlusMenuProps {
  items: AiInputMenuItem[]
  label?: string
  icon?: ReactNode
  className?: string
}

function ChevronRightIcon({ className }: { className?: string }) {
  return (
    <svg
      width={14}
      height={14}
      viewBox="0 0 14 14"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={className}
    >
      <path d="M5.25 3.5L8.75 7L5.25 10.5" />
    </svg>
  )
}

function ChevronLeftIcon({ className }: { className?: string }) {
  return (
    <svg
      width={14}
      height={14}
      viewBox="0 0 14 14"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={className}
    >
      <path d="M8.75 3.5L5.25 7L8.75 10.5" />
    </svg>
  )
}

const PLUS_MENU_SLIDE_TRANSITION = { duration: 0.18, ease: [0.22, 1, 0.36, 1] } as const

const plusMenuSlideVariants = {
  enter: (dir: number) => ({ opacity: 0, x: dir * 12 }),
  visible: { opacity: 1, x: 0 },
  exit: (dir: number) => ({ opacity: 0, x: dir * -12 }),
}

function PlusMenuRow({
  item,
  onNavigate,
}: {
  item: AiInputMenuItem
  onNavigate: (submenu: { label: string; items: AiInputMenuItem[] }) => void
}) {
  if (item.type === 'separator') {
    return <DropdownMenuSeparator />
  }

  if (item.type === 'toggle') {
    return (
      <div className="flex min-h-11 w-full items-center justify-between gap-3 rounded-md px-3 py-2.5 text-sm text-(--color-fg)">
        <span className="flex min-w-0 flex-1 items-center gap-2 truncate">
          {item.icon && (
            <span aria-hidden="true" className="shrink-0 text-(--color-muted)">
              {item.icon}
            </span>
          )}
          {item.label}
        </span>
        <Switch checked={item.checked} onCheckedChange={item.onCheckedChange} />
      </div>
    )
  }

  if (item.type === 'submenu') {
    return (
      <button
        type="button"
        className={cn(
          'relative flex min-h-11 w-full cursor-pointer items-center justify-between gap-3 rounded-md px-3 py-2.5 text-start text-sm text-(--color-fg) outline-none',
          'hover:bg-(--color-surface-2) focus-visible:bg-(--color-surface-2)',
          'transition-colors duration-(--motion-dur-fast) motion-reduce:transition-none',
        )}
        onClick={() => onNavigate({ label: item.label, items: item.items })}
        onPointerDown={(e) => e.preventDefault()}
      >
        <span className="flex min-w-0 flex-1 items-center gap-2 truncate">
          {item.icon && (
            <span aria-hidden="true" className="shrink-0 text-(--color-muted)">
              {item.icon}
            </span>
          )}
          {item.label}
        </span>
        <ChevronRightIcon className="shrink-0 text-(--color-muted)" />
      </button>
    )
  }

  return (
    <DropdownMenuItem disabled={item.disabled} onClick={item.onSelect} textValue={item.label}>
      {item.icon && (
        <span aria-hidden="true" className="shrink-0 text-(--color-muted)">
          {item.icon}
        </span>
      )}
      <span className="flex-1 truncate">{item.label}</span>
      {item.shortcut && (
        <span className="shrink-0 text-xs tabular-nums text-(--color-muted)">{item.shortcut}</span>
      )}
    </DropdownMenuItem>
  )
}

export function AiInputPlusMenu({
  items,
  label = 'More actions',
  icon,
  className,
}: AiInputPlusMenuProps) {
  const [submenu, setSubmenu] = useState<{ label: string; items: AiInputMenuItem[] } | null>(null)
  const [slideDir, setSlideDir] = useState(1)

  const navigateTo = useCallback((next: { label: string; items: AiInputMenuItem[] }) => {
    setSlideDir(1)
    setSubmenu(next)
  }, [])

  const navigateBack = useCallback(() => {
    setSlideDir(-1)
    setSubmenu(null)
  }, [])

  const activeItems = submenu?.items ?? items

  return (
    <DropdownMenu
      onOpenChange={(open) => {
        if (!open) setSubmenu(null)
      }}
    >
      <DropdownMenuTrigger
        showChevron={false}
        aria-label={label}
        className={cn(
          'inline-flex size-8 shrink-0 min-h-0 w-8 items-center justify-center rounded-full supports-[corner-shape:squircle]:corner-squircle border-0 bg-transparent p-0 text-(--color-muted) hover:bg-(--color-surface-2) hover:text-(--color-fg)',
          className,
        )}
      >
        {icon ?? <PlusIcon />}
      </DropdownMenuTrigger>
      <DropdownMenuContent className="overflow-hidden">
        <AnimatePresence mode="popLayout" initial={false} custom={slideDir}>
          <motion.div
            key={submenu?.label ?? 'root'}
            custom={slideDir}
            variants={plusMenuSlideVariants}
            initial="enter"
            animate="visible"
            exit="exit"
            transition={PLUS_MENU_SLIDE_TRANSITION}
          >
            {submenu && (
              <button
                type="button"
                className={cn(
                  'relative flex min-h-11 w-full cursor-pointer items-center gap-2 rounded-md px-3 py-2.5 text-start text-sm font-medium text-(--color-fg) outline-none',
                  'hover:bg-(--color-surface-2) focus-visible:bg-(--color-surface-2)',
                  'transition-colors duration-(--motion-dur-fast) motion-reduce:transition-none',
                )}
                onClick={navigateBack}
                onPointerDown={(e) => e.preventDefault()}
              >
                <ChevronLeftIcon className="shrink-0 text-(--color-muted)" />
                {submenu.label}
              </button>
            )}
            {activeItems.map((item) => (
              <PlusMenuRow key={item.value} item={item} onNavigate={navigateTo} />
            ))}
          </motion.div>
        </AnimatePresence>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

export interface AiInputSettingOption {
  value: string
  label: string
  description?: string
}

export interface AiInputSettingGroup {
  id: string
  label: string
  options: AiInputSettingOption[]
}

export interface AiInputSettingsDropdownProps {
  groups: AiInputSettingGroup[]
  values: Record<string, string>
  onValueChange: (groupId: string, value: string) => void
  effortLevel?: AiInputEffortLevel
  label?: string
  className?: string
}

export function AiInputSettingsDropdown({
  groups,
  values,
  onValueChange,
  effortLevel,
  label = 'Settings',
  className,
}: AiInputSettingsDropdownProps) {
  const triggerLabel = groups
    .map((group) => group.options.find((o) => o.value === values[group.id])?.label)
    .filter(Boolean)
    .join(', ')

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        showChevron={false}
        aria-label={`${label}: ${triggerLabel}`}
        className={cn(
          'inline-flex min-h-0 w-auto items-center gap-1.5 rounded-full border-0 bg-transparent px-2 py-1 text-xs font-medium text-(--color-muted) hover:bg-(--color-surface-2) hover:text-(--color-fg)',
          className,
        )}
      >
        {effortLevel && <AiInputEffortBarsIcon level={effortLevel} className="shrink-0" />}
        <span className="truncate">{triggerLabel}</span>
        <svg
          width={10}
          height={10}
          viewBox="0 0 14 14"
          fill="none"
          stroke="currentColor"
          strokeWidth={1.5}
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
        >
          <path d="M3.5 5.25L7 8.75L10.5 5.25" />
        </svg>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start">
        {groups.map((group, index) => (
          <DropdownMenuGroup key={group.id} label={index === 0 ? undefined : group.label}>
            {group.options.map((option) => {
              const selected = values[group.id] === option.value
              return (
                <DropdownMenuItem
                  key={option.value}
                  textValue={option.label}
                  onClick={() => onValueChange(group.id, option.value)}
                >
                  <span className="min-w-0 flex-1">
                    <span className="block truncate">{option.label}</span>
                    {option.description && (
                      <span className="block truncate text-xs text-(--color-muted)">
                        {option.description}
                      </span>
                    )}
                  </span>
                  {selected && (
                    <svg
                      width={16}
                      height={16}
                      viewBox="0 0 16 16"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth={2}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      aria-hidden="true"
                      className="shrink-0 text-(--color-accent)"
                    >
                      <path d="M3 8.5l3.5 3.5L13 4.5" />
                    </svg>
                  )}
                </DropdownMenuItem>
              )
            })}
          </DropdownMenuGroup>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

/* ─── Controlled/Uncontrolled hook ─── */

function useControlledState(
  controlledValue: string | undefined,
  defaultValue: string | undefined,
  onValueChange: ((value: string) => void) | undefined,
): [string, (next: string) => void] {
  const [internal, setInternal] = useState(defaultValue ?? '')
  const isControlled = controlledValue !== undefined
  const value = isControlled ? controlledValue : internal

  const setValue = useCallback(
    (next: string) => {
      if (!isControlled) setInternal(next)
      onValueChange?.(next)
    },
    [isControlled, onValueChange],
  )

  return [value, setValue]
}

/* ─── Props ─── */

export interface AiInputProps {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  onSubmit?: (value: string) => void
  streaming?: boolean
  onStop?: () => void
  placeholder?: string
  maxRows?: number
  disabled?: boolean
  name?: string
  startSlot?: ReactNode
  endSlot?: ReactNode
  className?: string
}

/* ─── Component ─── */

export const AiInput = forwardRef<HTMLTextAreaElement, AiInputProps>(
  (
    {
      value: controlledValue,
      defaultValue,
      onValueChange,
      onSubmit,
      streaming = false,
      onStop,
      placeholder = 'Type a message…',
      maxRows = 6,
      disabled = false,
      name,
      startSlot,
      endSlot,
      className,
    },
    ref,
  ) => {
    const reduceMotion = useReducedMotion()
    const internalRef = useRef<HTMLTextAreaElement>(null)
    const [launched, setLaunched] = useState(false)
    const launchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

    // Merge refs
    const setRefs = useCallback(
      (el: HTMLTextAreaElement | null) => {
        ;(internalRef as React.MutableRefObject<HTMLTextAreaElement | null>).current = el
        if (typeof ref === 'function') ref(el)
        else if (ref) (ref as React.MutableRefObject<HTMLTextAreaElement | null>).current = el
      },
      [ref],
    )

    const [value, setValue] = useControlledState(controlledValue, defaultValue, onValueChange)

    /* ─── Auto-grow ─── */

    useIsoLayoutEffect(() => {
      const el = internalRef.current
      if (!el) return
      el.style.height = 'auto'
      const computed = getComputedStyle(el)
      const lineHeight = parseFloat(computed.lineHeight)
      if (Number.isNaN(lineHeight)) return
      const max = lineHeight * maxRows
      const next = Math.min(el.scrollHeight, max)
      el.style.height = `${next}px`
      el.style.overflowY = el.scrollHeight > max ? 'auto' : 'hidden'
    }, [value, maxRows])

    /* ─── Send logic ─── */

    const trimmed = value.trim()
    const canSend = !disabled && !streaming && trimmed.length > 0

    const handleSubmit = useCallback(() => {
      if (!canSend) return

      // Trigger launch animation
      if (!reduceMotion) {
        setLaunched(true)
        launchTimerRef.current = setTimeout(() => {
          setLaunched(false)
        }, 400)
      }

      onSubmit?.(trimmed)
    }, [canSend, onSubmit, trimmed, reduceMotion])

    const handleStop = useCallback(() => {
      onStop?.()
    }, [onStop])

    /* ─── Keyboard ─── */

    const handleKeyDown = useCallback(
      (e: ReactKeyboardEvent<HTMLTextAreaElement>) => {
        if (e.nativeEvent.isComposing) return
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault()
          if (streaming) {
            handleStop()
          } else {
            handleSubmit()
          }
        }
      },
      [streaming, handleSubmit, handleStop],
    )

    /* ─── Cleanup ─── */

    useEffect(() => {
      return () => {
        if (launchTimerRef.current !== null) {
          clearTimeout(launchTimerRef.current)
        }
      }
    }, [])

    /* ─── Button state ─── */

    const showStop = streaming
    const buttonDisabled = !streaming && !canSend

    return (
      <div
        className={cn(
          'relative flex min-h-11 items-end gap-2 rounded-lg supports-[corner-shape:squircle]:corner-squircle border border-(--color-border) bg-(--color-card) px-3.5 py-2',
          'transition-colors duration-(--motion-dur-fast) motion-reduce:transition-none',
          'focus-within:border-(--color-accent)',
          disabled && 'opacity-50 pointer-events-none',
          className,
        )}
      >
        <AnimatePresence>{launched && <SendWave reduceMotion={!!reduceMotion} />}</AnimatePresence>

        {startSlot && <div className="flex shrink-0 items-center self-end pb-0.5">{startSlot}</div>}

        {/* Textarea */}
        <textarea
          ref={setRefs}
          value={value}
          onChange={(e) => setValue(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          disabled={disabled}
          name={name}
          rows={1}
          aria-label={placeholder}
          className={cn(
            'w-full min-h-[1.5rem] resize-none bg-transparent text-sm text-foreground outline-none',
            'placeholder:text-muted-foreground',
          )}
          style={{ fieldSizing: 'content' } as React.CSSProperties}
        />

        {/* End slot */}
        {endSlot && <div className="flex shrink-0 items-center self-end pb-0.5">{endSlot}</div>}

        {/* Send / Stop button */}
        <button
          type="button"
          onClick={showStop ? handleStop : handleSubmit}
          onPointerDown={(e) => e.preventDefault()}
          disabled={buttonDisabled}
          aria-label={showStop ? 'Stop generation' : 'Send message'}
          className={cn(
            'relative flex shrink-0 items-center justify-center size-8 rounded-full squircle cursor-pointer outline-none',
            'bg-foreground text-background',
            'transition-[opacity,transform] duration-(--motion-dur-fast) motion-reduce:transition-none',
            'active:scale-95 motion-reduce:active:scale-100',
            'disabled:opacity-40 disabled:pointer-events-none',
            'focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-1 focus-visible:ring-offset-background',
          )}
        >
          <AnimatePresence mode="wait" initial={false}>
            {showStop ? (
              <motion.span
                key="stop"
                className="flex items-center justify-center"
                initial={reduceMotion ? false : { opacity: 0, scale: 0.9 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={reduceMotion ? undefined : { opacity: 0, scale: 0.9 }}
                transition={reduceMotion ? { duration: 0 } : { duration: 0.12 }}
              >
                <StopIcon />
              </motion.span>
            ) : (
              <motion.span
                key="send"
                className="flex items-center justify-center"
                initial={reduceMotion ? false : { opacity: 0, scale: 0.9 }}
                animate={
                  launched && !reduceMotion
                    ? { opacity: 0, y: -8, scale: 0.9 }
                    : { opacity: 1, y: 0, scale: 1 }
                }
                exit={reduceMotion ? undefined : { opacity: 0, scale: 0.9 }}
                transition={
                  reduceMotion
                    ? { duration: 0 }
                    : launched
                      ? { duration: 0.25, ease: [0.22, 1, 0.36, 1] }
                      : springs.fast
                }
              >
                <SendIcon />
              </motion.span>
            )}
          </AnimatePresence>
        </button>
      </div>
    )
  },
)

AiInput.displayName = 'AiInput'

/* ─── Preview helper (for fallback use) ─── */

export function AiInputPreview() {
  const [value, setValue] = useState('')
  const [webSearch, setWebSearch] = useState(false)
  const [settings, setSettings] = useState<Record<string, string>>({
    model: 'fast',
    effort: 'medium',
  })

  return (
    <div className="flex h-full w-full items-center justify-center p-6">
      <div className="flex w-full max-w-md flex-col gap-2">
        <AiInput
          value={value}
          onValueChange={setValue}
          onSubmit={() => setValue('')}
          placeholder="Ask anything..."
          startSlot={
            <AiInputPlusMenu
              items={[
                { type: 'action', value: 'attach', label: 'Attach file' },
                { type: 'action', value: 'photo', label: 'Add photo' },
                { type: 'separator', value: 'sep-1' },
                {
                  type: 'toggle',
                  value: 'web-search',
                  label: 'Web search',
                  checked: webSearch,
                  onCheckedChange: setWebSearch,
                },
                { type: 'separator', value: 'sep-2' },
                {
                  type: 'submenu',
                  value: 'connect',
                  label: 'Connect apps',
                  items: [
                    { type: 'action', value: 'drive', label: 'Google Drive' },
                    { type: 'action', value: 'notion', label: 'Notion' },
                    { type: 'action', value: 'github', label: 'GitHub' },
                  ],
                },
              ]}
            />
          }
        />
        <AiInputSettingsDropdown
          groups={[
            {
              id: 'model',
              label: 'Model',
              options: [
                { value: 'fast', label: 'Fast', description: 'Quick, everyday answers' },
                { value: 'thinking', label: 'Thinking', description: 'Slower, more thorough' },
              ],
            },
            {
              id: 'effort',
              label: 'Effort',
              options: [
                { value: 'low', label: 'Low' },
                { value: 'medium', label: 'Medium' },
                { value: 'high', label: 'High' },
              ],
            },
          ]}
          values={settings}
          onValueChange={(groupId, val) => setSettings((prev) => ({ ...prev, [groupId]: val }))}
          effortLevel={settings.effort as AiInputEffortLevel}
        />
      </div>
    </div>
  )
}

export const durations = {
  instant: '50ms',
  fast: '120ms',
  base: '200ms',
  slow: '320ms',
} as const

export const easings = {
  out: 'cubic-bezier(0.22, 1, 0.36, 1)',
  inOut: 'cubic-bezier(0.65, 0, 0.35, 1)',
} as const

export const springs = {
  fast: { type: 'spring', stiffness: 400, damping: 30, mass: 0.8 },
  press: { type: 'spring', stiffness: 700, damping: 32, mass: 1 },
  moderate: { type: 'spring', stiffness: 300, damping: 24, mass: 1 },
  settle: { type: 'spring', stiffness: 260, damping: 26, mass: 1 },
} as const
